<span class="line"><span style="color:#B392F0;">kubectl</span><span style="color:#9ECBFF;"> port-forward</span><span style="color:#9ECBFF;"> svc/prometheus</span><span style="color:#9ECBFF;"> 9090:9090</span><span style="color:#79B8FF;"> -n</span><span style="color:#9ECBFF;"> monitoring</span></span>
